#include <bits/stdc++.h>
#define pb push_back
#define x first
#define y second

using namespace std;
typedef long long INT;
typedef pair <int, int> pii;
typedef vector <int> VI;

#define NN 6555
struct edge {
	int to, capacity, cost, rev;
	edge() {}
	edge(int to,int _capacity,int _cost,int _rev):
		to(to), capacity(_capacity), cost(_cost), rev(_rev) {}
};

const int inf=0x3f3f3f3f;

struct Min_Cost_Max_Flow {
	int V, H[NN + 5], dis[NN +5], PreV[NN +5], PreE[NN + 5];
	vector<edge> G[NN + 5];
	void Init(int n) {
		V = n;
		for (int i = 0; i <= V; ++i) G[i].clear();
   	}
	void add_edge(int from, int to, int cap, int cost) {
		G[from].push_back(edge(to, cap, cost, G[to].size()));
		G[to].push_back(edge(from,0, -cost, G[from].size() - 1));
	}
	int minCost(int s, int t, int f) {
		int flow = 0;
		int res = 0;
		fill(H, H +1 + V, 0);
		while (f) {
   			priority_queue <pii, vector<pii>, greater<pii> > q;
   			fill(dis, dis + 1 + V, inf);
   			dis[s] = 0; q.push(pii(0, s));
			while (!q.empty()) {
   				pii now = q.top(); q.pop();
				int v = now.second;
				if (dis[v] < now.first)continue;
				for (int i = 0; i < G[v].size(); ++i) {
   					edge& e = G[v][i];
					if (e.capacity > 0 && dis[e.to] > dis[v] + e.cost + H[v] - H[e.to]) {
   						dis[e.to] = dis[v] + e.cost + H[v] - H[e.to];
   						PreV[e.to] = v;
   						PreE[e.to] = i;
   						q.push(pii(dis[e.to], e.to));
	   				}
	   			}
	   		}
			if (dis[t] == inf)   break;
			for (int i = 0; i <= V; ++i)H[i] += dis[i];
			int d = f;
			for (int v = t; v != s; v = PreV[v])d = min(d, G[PreV[v]][PreE[v]].capacity);
   			f -= d; flow += d; res += d*H[t];
			for (int v = t; v != s; v = PreV[v]) {
   				edge& e = G[PreV[v]][PreE[v]];
   				e.capacity -= d;
   				G[v][e.rev].capacity += d;
			}
   		}
		return res;
   	}
} mcmf;

int main (){
#ifndef ONLINE_JUDGE
	freopen ("in.in", "r", stdin);
	freopen ("out.out", "w", stdout);
#endif

	int n, m, k, c, d;

	cin >> n >> m >> k >> c >> d;

	mcmf.Init(n*(n+55)+2);
	for(int i=0; i<k; i++){
		int u; cin >> u;
		mcmf.add_edge(0, u, 1, 0);
	}

	vector <pii> edge=vector <pii> (m);
	for(int i=0; i<m; i++) cin >> edge[i].x >> edge[i].y;

	int tar=n*(n+55)+1;
	for(int t=0; t<n+54; t++){
		for(pii e : edge){
			for(int j=1; j<=k; j++){
				mcmf.add_edge(e.x+t*n, e.y+(t+1)*n, 1, c+d*(j*2-1));
				mcmf.add_edge(e.y+t*n, e.x+(t+1)*n, 1, c+d*(j*2-1));
			}
		}
		for(int i=2; i<=n; i++){
			mcmf.add_edge(i+t*n, i+(t+1)*n, k, c);
		}
		mcmf.add_edge(1+t*n, tar, k, 0);
	}

	cout << mcmf.minCost(0, tar, k) << endl;

	return 0;
}


